import base64
with open(r'SIH\dashboard\app.js', 'r', encoding='utf-8') as f:
    text = f.read()

start = text.find('window.renderRecentSearches = function() {')
end = text.find('};', start) + 2

b64 = ""
new_func = base64.b64decode(b64).decode('utf-8')

with open(r'SIH\dashboard\app.js', 'w', encoding='utf-8') as f:
    f.write(text[:start] + new_func + text[end:])
